mapper.select:
SELECT t.id, t.name, t.api_config_id, a.name AS api_config_name, t.datasource_id,
       d.name AS datasource_name, d.db_type AS datasource_db_type,
       t.target_schema, t.target_table,
       t.write_mode, t.merge_keys, t.auto_create_table, t.batch_size, t.retry_times, t.timeout_ms, t.alarm_enabled,
       t.schedule_type, t.cron_expression, t.status, t.remark, t.create_time, t.update_time
FROM APIGRAB_COLLECT_TASK t
LEFT JOIN APIGRAB_API_CONFIG a ON t.api_config_id = a.id
LEFT JOIN APIGRAB_DATASOURCE_CONFIG d ON t.datasource_id = d.id

    AND t.name LIKE CONCAT('%', #{name}, '%')
    AND t.api_config_id = #{apiConfigId}
    AND t.datasource_id = #{datasourceId}
    AND t.write_mode = #{writeMode}
    AND t.schedule_type = #{scheduleType}
    AND t.status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.TaskStatusTypeHandler}

ORDER BY t.id DESC

mapper.update:
UPDATE APIGRAB_COLLECT_TASK
name = #{name}, api_config_id = #{apiConfigId}, datasource_id = #{datasourceId}, target_schema = #{targetSchema}, target_table = #{targetTable}, write_mode = #{writeMode}, merge_keys = #{mergeKeys}, auto_create_table = #{autoCreateTable}, batch_size = #{batchSize}, retry_times = #{retryTimes}, timeout_ms = #{timeoutMs}, alarm_enabled = #{alarmEnabled}, schedule_type = #{scheduleType}, cron_expression = #{cronExpression}, status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.TaskStatusTypeHandler}, remark = #{remark},
WHERE id = #{id}
